                                  '            }\n'
                                  '            Button("merchant.hints.restart") { revealed = 0 }\n'
                                  '                .disabled(revealed == '
                                  '0).accessibilityIdentifier("merchant.hints.preview.restart")\n'
                                  '        }.onChange(of: hints) { _, _ in revealed = 0 }\n'
                                  '    }\n'
                                  '}\n'
