                                  '    }\n'
                                  '    public mutating func add() {\n'
                                  '        guard canAdd else { return }\n'
                                  '        rows.append(""); isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func remove(at index: Int) {\n'
                                  '        guard rows.count > 1, rows.indices.contains(index) else { return '
