                                  '        if rows.contains(where: { $0.rangeOfCharacter(from: .newlines) != '
                                  'nil }) { return "merchant.ruleSteps.oneLine" }\n'
                                  '        if rows.contains(where: { $0.utf16.count > Self.maximumStepLength '
                                  '}) { return "merchant.ruleSteps.textLimit" }\n'
                                  '        return nil\n'
                                  '    }\n'
                                  '}\n'
                                  '\n'
                                  '/// Existing Mini hint group. The enabled switch is editor state, never a '
                                  'backend flag.\n'
                                  'public struct MerchantTemplateHints: Equatable {\n'
                                  '    public enum Field: String, CaseIterable, Identifiable {\n'
                                  '        case hint1, hint2, answerReveal\n'
                                  '        public var id: String { rawValue }\n'
                                  '        public var titleKey: String { "merchant.hints." + rawValue }\n'
                                  '    }\n'
                                  '    private let sourceFields: [String: String]\n'
                                  '    private let sourceMethod: MerchantTemplateMethod?\n'
                                  '    private var values: [Field: String]\n'
                                  '    public private(set) var enabled: Bool\n'
                                  '    public private(set) var isEdited = false\n'
                                  '    public init(hint1: String? = nil, hint2: String? = nil, answerReveal: '
                                  'String? = nil,\n'
                                  '                method: MerchantTemplateMethod? = nil) {\n'
                                  '        sourceFields = ["hint1": hint1, "hint2": hint2, "answerReveal": '
                                  'answerReveal].compactMapValues { $0 }\n'
                                  '        // An absent/empty group has no method-dependent source state. '
                                  'Keep legacy\n'
                                  '        // no-hint templates equivalent to a freshly constructed empty '
                                  'group.\n'
