                                  '.answerReveal: answerReveal ?? ""]\n'
                                  '        enabled = sourceFields.values.contains { !$0.isEmpty }\n'
                                  '    }\n'
                                  '    public static func supports(_ method: MerchantTemplateMethod?) -> '
                                  'Bool {\n'
                                  '        method == .secretWord || method == .quiz || method == .gps\n'
                                  '    }\n'
                                  '    public func text(_ field: Field) -> String { values[field] ?? "" }\n'
                                  '    public mutating func update(_ field: Field, text: String) {\n'
                                  '        guard enabled, values[field] != text else { return }\n'
                                  '        values[field] = text; isEdited = true\n'
                                  '    }\n'
                                  '    public mutating func setEnabled(_ value: Bool) {\n'
                                  '        guard enabled != value else { return }\n'
                                  '        enabled = value; isEdited = true\n'
                                  '        if !value { for field in Field.allCases { values[field] = "" } }\n'
