                                  '.whitespacesAndNewlines).isEmpty || imageReferenceCount > 0 }\n'
                                  '    }\n'
                                  '    private let sourceText: String?\n'
                                  '    private let sourceJSON: String?\n'
                                  '    private let sourceImageCount: Int\n'
                                  '    private let sourceBeats: [Beat]\n'
                                  '    private var nextID: Int\n'
                                  '    public let isEditable: Bool\n'
                                  '    public private(set) var beats: [Beat]\n'
                                  '    public private(set) var enabled: Bool\n'
                                  '    public private(set) var isEdited = false\n'
                                  '    public init(storyText: String? = nil, storyJSON: String? = nil) {\n'
                                  '        sourceText = storyText; sourceJSON = storyJSON\n'
                                  '        if let raw = storyJSON, !raw.isEmpty {\n'
                                  '            if let parsed = Self.parse(raw) {\n'
                                  '                beats = parsed.isEmpty ? [Beat(id: 1, text: storyText ?? '
                                  '"")] : parsed\n'
                                  '                isEditable = true; enabled = !parsed.isEmpty || '
                                  '!(storyText ?? "").isEmpty\n'
                                  '            } else {\n'
                                  '                beats = []; isEditable = false; enabled = true\n'
                                  '            }\n'
                                  '        } else {\n'
                                  '            beats = [Beat(id: 1, text: storyText ?? "")]; isEditable = '
                                  'true\n'
                                  '            enabled = !(storyText ?? "").isEmpty\n'
                                  '        }\n'
