                                  '}\n'
                                  '        nextID = beats.count + 1\n'
                                  '    }\n'
                                  '    private static func parse(_ raw: String) -> [Beat]? {\n'
                                  '        guard let array = try? JSONSerialization.jsonObject(with: '
                                  'Data(raw.utf8)) as? [[String: Any]] else { return nil }\n'
                                  '        var result: [Beat] = []\n'
                                  '        for (index, item) in array.enumerated() {\n'
                                  '            guard Set(item.keys).isSubset(of: ["text", "tag", "imgs", '
                                  '"img"]) else { return nil }\n'
                                  '            for key in ["text", "tag", "img"] {\n'
                                  '                if let value = item[key], !(value is NSNull), !(value is '
                                  'String) { return nil }\n'
                                  '            }\n'
                                  '            var images: [String]?\n'
                                  '            if let value = item["imgs"], !(value is NSNull) {\n'
