                                  '    if budget != _CLUB_BUDGET:\n'
                                  "        raise ValueError('Unreviewed complete club leaderboard budget')\n"
                                  '    root, directory = Path(root), Path(directory)\n'
                                  "    if directory.absolute() != (root / 'Tests/AppUITests').absolute():\n"
                                  "        raise ValueError('Club budget must read the supplied actual "
                                  "current UI directory')\n"
                                  "    for relative, expected in budget['source_sha256'].items():\n"
                                  '        path = directory / Path(relative).name if '
                                  "relative.startswith('Tests/AppUITests/') else root / relative\n"
                                  '        if digest(path.read_bytes()) != expected:\n'
                                  "            raise ValueError('Changed club whole-method budget source: ' "
                                  '+ relative)\n'
                                  '    text = (directory / '
                                  "'ClubLeaderboardMemberFlowTests.swift').read_text()\n"
                                  "    if len(re.findall(r'(?m)^    func testLeaderboard\\w+\\(', text)) != "
                                  '6:\n'
                                  "        raise ValueError('Changed complete club UI method inventory')\n"
                                  '    expected_waits = [40, 30, 62, 15, 15, 15]\n'
                                  '    expected_reveals = [3, 2, 2, 1, 1, 1]\n'
                                  '    expected_ax = [10, 10, 20, 10, 5, 5]\n'
                                  '    expected_caps = [260, 210, 260, 160, 150, 150]\n'
                                  '    costs = []\n'
                                  "    for i, (name, row) in enumerate(budget['methods'].items()):\n"
                                  "        match = re.search(r'(?m)^    func ' + re.escape(name) + "
                                  "r'\\b[\\s\\S]*?^    }', text)\n"
                                  '        if match is None or digest(match.group().encode()) != '
                                  "row['declaration_sha256']:\n"
                                  "            raise ValueError('Changed complete club method declaration: ' "
                                  '+ name)\n'
                                  '        wait, reveals, ax = expected_waits[i], expected_reveals[i], '
                                  'expected_ax[i]\n'
                                  '        # 90 covers launch/reset/termination and failure capture; each '
                                  'reveal\n'
                                  '        # charges all eleven viewport evaluations and up to ten '
                                  'gestures.\n'
                                  '        unrounded = 90 + wait + reveals * 40 + ax\n'
                                  '        complete = math.ceil(unrounded / 10) * 10\n'
                                  "        if (row['measured'] is not False or row['explicit_wait_seconds'] "
                                  '!= wait\n'
                                  "                or row['reveal_calls_with_loop_expansion'] != reveals\n"
                                  "                or row['lifecycle_and_failure_seconds'] != 90\n"
                                  "                or row['per_reveal_seconds'] != 40 or "
                                  "row['direct_ax_allowance_seconds'] != ax\n"
                                  "                or row['unrounded_complete_seconds'] != unrounded\n"
                                  "                or row['complete_seconds'] != complete or complete != "
